mapper.insert:
INSERT INTO ainer_workspace_authorization_audit (
    id, workspace_id, actor_subject_id, target_subject_id,
    action, decision, reason_code, occurred_at
) VALUES (
    #{id}, #{workspaceId}, #{actorSubjectId}, #{targetSubjectId},
    #{action}, #{decision}, #{reasonCode}, #{occurredAt}
)

mapper.select:
SELECT SUM(total)
FROM (
    SELECT COUNT(*) AS total
    FROM ainer_workspace_authorization_audit
    WHERE workspace_id = #{workspaceId}
    UNION ALL
    SELECT COUNT(*) AS total
    FROM ainer_workspace_authorization_audit_archive
    WHERE workspace_id = #{workspaceId}
) counts

SELECT id, workspace_id, actor_subject_id, target_subject_id, action, decision, reason_code, occurred_at FROM ( SELECT id, workspace_id, actor_subject_id, target_subject_id, action, decision, reason_code, occurred_at FROM ainer_workspace_authorization_audit UNION ALL SELECT id, workspace_id, actor_subject_id, target_subject_id, action, decision, reason_code, occurred_at FROM ainer_workspace_authorization_audit_archive ) audit WHERE workspace_id = #{workspaceId}
AND (occurred_at, id) > (#{afterOccurredAt}, #{afterId})
ORDER BY occurred_at, id LIMIT #{limit}
